$lang['information-display_condition'] = 'காண்பிக்கும் நிபந்தனை: பின்வரும் நிபந்தனைகள் பூர்த்தி செய்யப்பட்டால் மட்டுமே இந்த புலம் காண்பிக்கப்படும். சரிபார்க்கப்படும் புலம் கீழ்காணும் நிலையான வகைகளில் ஒன்றாக இருக்க வேண்டும்: கீழே விழும் பட்டியல், செக் பாக்ஸ் பட்டியல், ரேடியோ பொத்தான்கள், இயக்கக்கூடிய முக்கியசொல் அல்லது வகை மரம். குழு தேடல் வடிகட்டியின் வடிவத்தைப் பயன்படுத்துகிறது, உதா: shortname=value1|value2, shortnamea=validoptiona;shortnameb=validoptionb1|validoptionb2';
