$lang['map_introtext1'] = 'கீழே உள்ள வரைபடம், தேடல் முடிவுகளில் உள்ள மற்றும் இடம் தொடர்புடைய வளங்களை காட்டுகிறது. குறியீடு நிறம் வள வகை அல்லது தனிப்பயன் மெட்டாடேட்டா புலத்தால் (வரைபடத்தின் கீழ் உள்ள விசை) அமைக்கப்பட்டுள்ளது. குறியீடுகள் ஒருவருக்கொருவர் மோதும் போது, பச்சை நிற கிளஸ்டரிங் பயன்படுத்தப்படுகிறது, அதில் கிளஸ்டர் செய்யப்பட்ட குறியீடுகளின் எண்ணிக்கை காட்டப்படுகிறது; கிளஸ்டரை பெரிதாக்க அல்லது இரட்டை கிளிக் செய்யவும். தனிப்பட்ட குறியீடுகளை கிளிக் செய்து அந்த வளத்தின் முன்னோட்ட படத்துடன் ஒரு பாப்அப் திறக்கவும். முன்னோட்ட படத்தை கிளிக் செய்து அந்த வளத்திற்கான விண்டோவை திறக்கவும். குறியீடுகளின் மேல் மவுஸ் கொண்டு செல்லும் போது இடம் இணைவு காண்பிக்கப்படும். மேல் வலது பகுதியில் உள்ள வரைபட பொத்தானை பயன்படுத்தி அடிப்படை வரைபடத்தை மாற்றவும். கீழ் இடது பகுதியில் உள்ள வரைபட பொத்தானை பயன்படுத்தி வரைபடத்தை PNG கோப்பாக சேமிக்கவும்.';
$lang['edit_map_introtext'] = 'பார்வையிட விரும்பும் வரைபடத்தை பான் செய்து பெரிதாக்கவும், பின்னர் வரைபடத்தில் கிளிக் செய்து வளத்தின் இடம் குறியீட்டை அமைக்கவும். சமீபத்திய இடத்தை சேமிக்க \'சேமி\' பொத்தானை அழுத்தவும், பின்னர் \'வளத் திருத்தத்திற்கு அல்லது தொகுப்பை இடம் கண்டறிய\' திரும்ப கிளிக் செய்யவும். குறிப்பிட்ட இடம் அல்லது புவியியல் பெயரை தேட மேலே வலது பகுதியில் உள்ள தேடல் பொத்தானை பயன்படுத்தவும். அடிப்படை வரைபடத்தை மாற்ற மேலே வலது பகுதியில் உள்ள வரைபட அடுக்கு பொத்தானை பயன்படுத்தவும். கீழ் இடது பகுதியில் உள்ள வரைபட பொத்தானை பயன்படுத்தி வரைபடத்தை PNG கோப்பாக சேமிக்கவும்.';
