$lang['collection_manage__findpublic'] = 'பொது தொகுப்புகள் என்பது அமைப்பின் பயனர்களால் பரவலாகக் கிடைக்கும் வளக் குழுக்களாகும். பொது தொகுப்புகளை கண்டுபிடிக்க தொகுப்பு ஐடி அல்லது தொகுப்பு பெயர் அல்லது பயனர் பெயரின் ஒரு பகுதியை உள்ளிடவும். அவற்றை உங்கள் தொகுப்பு பட்டியலில் சேர்த்து வளங்களை அணுகவும்.';
$lang['collection_manage__introtext'] = 'வளங்களை ஒன்றாகக் குழுவாக்கி உங்கள் பணியை ஒழுங்குபடுத்து. உங்கள் பணிப்பாணிக்கு ஏற்ப \'தொகுப்புகள்\' உருவாக்கவும். நீங்கள் தனித்தனியாக பணியாற்றும் திட்டங்களின் கீழ் வளங்களை குழுவாக்க விரும்பலாம், ஒரு திட்டக் குழுவில் வளங்களை பகிரலாம் அல்லது உங்கள் பிடித்த வளங்களை ஒரே இடத்தில் வைத்திருக்கலாம். உங்கள் பட்டியலில் உள்ள அனைத்து தொகுப்புகளும் திரையின் கீழே உள்ள \'என் தொகுப்புகள்\' பகுதியில் தோன்றும்.';
