$lang['collection_public__introtext'] = 'பொது தொகுப்புகள் மற்ற பயனர்களால் உருவாக்கப்பட்டவை.';
$lang['contact__contact'] = 'உங்கள் தொடர்பு விவரங்கள் இங்கே.';
$lang['contribute__introtext'] = 'நீங்கள் உங்கள் சொந்த வளங்களை பங்களிக்கலாம். முதலில் ஒரு வளத்தை உருவாக்கும் போது அது "சமர்ப்பிப்பு காத்திருப்பு" நிலைமையில் இருக்கும். உங்கள் கோப்பை பதிவேற்றியதும் புலங்களைத் திருத்தியதும், நிலை புலத்தை "கண்ணோட்டம் காத்திருப்பு" ஆக அமைக்கவும். பின்னர் அது வளக் குழுவால் மதிப்பாய்வு செய்யப்படும்.';
