$lang['done__research_request'] = 'ஆராய்ச்சி குழுவின் ஒரு உறுப்பினர் உங்கள் கோரிக்கைக்கு நியமிக்கப்படுவார். செயல்முறை முழுவதும் மின்னஞ்சல் மூலம் தொடர்பில் இருப்போம், மற்றும் ஆராய்ச்சி முடிந்ததும் பரிந்துரைக்கப்படும் அனைத்து வளங்களுக்குமான இணைப்புடன் ஒரு மின்னஞ்சலை நீங்கள் பெறுவீர்கள்.';
