$lang['oj_purge_duplicates_collection_refs_help'] = 'நகல் கண்டறிதலுக்கான பரப்பளவாக தொகுப்புகளை அமைக்கிறது. தொகுப்புகளில் அனைத்து நகல்களும் இருக்க வேண்டியதில்லை, ஒன்றும் போதும். நகல்கள் பிறகு முழு அமைப்பிலும் செயலாக்கப்பட்டு தேர்ந்தெடுக்கப்பட்ட மேலாண்மை முறையால் அகற்றப்படும். தொகுப்புகள் காமா பிரிக்கப்பட்ட பட்டியலோ அல்லது வரம்புகளோ (எ.கா 100,105,110-115) மூலம் குறிப்பிடப்படலாம்.';
