$lang['oj_recreate_previews_refs_help'] = 'இந்த விருப்பத்தை அமைத்தல் எந்த குறியீடுகள் (வள அல்லது கலெக்ஷன் குறியீடுகள்) செயலாக்கத்திற்கு பயன்படுத்தப்படும் என்பதை கட்டுப்படுத்தும். செல்லுபடியாகும் உள்ளீடுகள் கமா பிரிக்கப்பட்ட பட்டியல்கள், வரம்புகள் மற்றும் விலங்குகள் அடங்கும் உதாரணமாக * அனைத்து குறியீடுகளையும் செயலாக்கும், 1-100 முதல் 100 குறியீடுகளையும் செயலாக்கும், 101-* 101 மற்றும் அதற்கு மேல் குறியீடுகளையும் செயலாக்கும், 1,3,5 1, 3 மற்றும் 5 குறியீடுகளையும் செயலாக்கும். இவை சேர்த்து தேவையான குறியீடுகளை இலக்காக அமைக்கலாம் உதாரணமாக 1,5-10,15-* 1, 5 முதல் 10 மற்றும் 15 முதல் குறியீடுகளை இலக்காக அமைக்கும்.';
$lang['oj_recreate_previews_use_existing_help'] = 'இந்த விருப்பத்தை அமைத்தல் வளங்களில் கைமுறையாக மாற்றப்பட்ட எந்த முன்னோட்டங்களையும் பாதுகாக்க முயலும். பயன்படுத்தப்படாவிட்டால், கைமுறையாக பதிவேற்றப்பட்ட முன்னோட்டங்கள் அசல் கோப்பிலிருந்து உருவாக்கப்பட்ட முன்னோட்டங்களால் மாற்றப்படும்.';
$lang['oj_recreate_previews_video_update_help'] = 'இந்த விருப்பத்தை அமைத்தல் தற்போதைய \'$ffmpeg_preview_extension\' நீட்சியுடன் பொருந்தாத எந்தவொரு வீடியோக்களையும் புதுப்பிக்கும். இது இந்த அமைப்பு மாற்றப்பட்டபோது, புதிய முன்னோட்டம் உருவாக்க வேண்டிய வளங்களை மட்டும் இலக்காக அமைக்க உதவும்.';
$lang['oj_recreate_previews_delete_existing_help'] = 'இந்த விருப்பத்தை அமைத்தல் மீண்டும் உருவாக்குவதற்கு முன் அனைத்து உள்ள முன்னோட்டங்களையும் அகக்கும்.';
$lang['oj_exif_data_blanks'] = 'EXIF தரவு இல்லாத போது புல மதிப்பை காலியாக விடுக';
$lang['oj_exif_data_overwrite'] = 'EXIF தரவு உள்ள இடங்களில் உள்ள புல மதிப்புகளை மீளெழுதுக';
$lang['oj_exif_data_field_refs_help'] = 'EXIF தரவை எடுக்க விரும்பும் புலங்களின் குறியீடுகள் இவை. இந்த புலங்களுக்கு "Exiftool புலம்" அமைக்கப்பட்டிருக்க வேண்டும். புலங்களை குறிப்பிட கமா பிரிக்கப்பட்ட பட்டியலை பயன்படுத்தலாம் உதாரணமாக 1,3,5.';
$lang['oj_exif_data_collection_refs_help'] = 'இந்த விருப்பத்தை அமைத்தல் பட்டியலிடப்பட்ட கலெக்ஷன்களில் உள்ள வளங்களுக்கே புதுப்பிப்பு செய்யப்படும். எந்த கலெக்ஷனும் குறிப்பிடப்படாவிட்டால் அனைத்து பொருத்தமான வளங்களுக்கும் EXIF தரவு புதுப்பிக்கப்படும். கலெக்ஷன்களை கமா பிரிக்கப்பட்ட பட்டியல் மற்றும் வரம்புகளாக குறிப்பிடலாம் உதாரணமாக 100,105,110-115';
$lang['oj_exif_data_blanks_help'] = 'இந்த விருப்பத்தை அமைத்தல் கோப்பில் உள்ள ஏதாவது உள்ளமைக்கப்பட்ட EXIF தரவு இல்லாவிட்டால் குறிப்பிடப்பட்ட புலம் காலியாகும்.';
$lang['oj_exif_data_overwrite_help'] = 'இந்த விருப்பத்தை அமைத்தல் கோப்பில் உள்ள EXIF தரவு இருந்தால், அது எந்தவொரு உள்ள மதிப்பையும் மீளெழுதும்.';
