$lang['storage_test_method'] = 'உயர் தரவு பரிமாற்றம் வேகமான சொத்து மாற்றங்களை குறிக்கிறது; அதிக கோப்பு செயல்பாட்டு விகிதங்கள் மற்றும் குறைந்த தாமதம் முன்னோட்ட அணுகலை அதிகரிக்கிறது. அளவீடுகள் கோப்பு அமைப்பு மற்றும் நெட்வொர்க் கேஷ், சேமிப்பு போட்டி மற்றும் ஒரே நேரத்தில் செயல்பாடுகளை உள்ளடக்கியவை. எழுதல்கள் பஃபர் செய்யப்பட்டு இயக்க முறைமைக்கு அனுப்பப்படுகின்றன, இயல்பான வட்டார நிலைத்தன்மையை கட்டாயப்படுத்தாமல்; வாசிப்புகள் முழுமையாக கேஷிலிருந்து வழங்கப்படலாம். இவை கண்காணிப்புகள், உறுதி செய்யப்பட்ட சேமிப்பு செயல்திறன் அல்லது பொருந்துதலுக்கான தேவைகள் அல்ல.';
$lang['storage_test_slow'] = 'ஆராய்ச்சி: குறைந்தது ஒரு அளவிடப்பட்ட செயல்பாடு ஒரு விநாடி அல்லது அதற்கு மேல் நேரம் எடுத்துள்ளது. பயனர்கள் தாமதங்களை அனுபவித்தால் சேமிப்பு போட்டி அல்லது நெட்வொர்க் தாமதத்தை ஆராயவும். இது பொருந்துதலின் தோல்வி அல்ல.';
$lang['storage_test_copy'] = 'நகல் சுருக்கம்';
$lang['storage_test_summary'] = 'ஆதரவு சேமிப்பு சோதனை சுருக்கம்';
$lang['storage_test_copied'] = 'சுருக்கம் நகலெடுக்கப்பட்டது.';
$lang['storage_test_select_copy'] = 'கீழே உள்ள சுருக்கத்தை தேர்ந்தெடுத்து நகலெடுக்கவும்.';
$lang['storage_test_denied'] = 'உள்ளமைப்பு சரிபார்ப்பு அணுகல் கொண்ட உள்நுழைந்த நிர்வாகிகள் மட்டுமே இந்த சோதனையை இயக்க முடியும்.';
$lang['storage_test_invalid'] = 'தவறான அல்லது காலாவதியான சேமிப்பு சோதனை கோரிக்கை. உள்ளமைப்பு சரிபார்ப்பை மீண்டும் ஏற்றவும்.';
$lang['storage_test_busy'] = 'மற்றொரு சேமிப்பு சோதனை கோரிக்கை அல்லது சோதனை செயல்பாட்டில் உள்ளது. அது முடிவடைய அல்லது இரண்டாவது நிமிடத்திற்கு பிறகு விட்டு வைக்கப்பட்ட சுத்தம் முடிவடைய காத்திருக்கவும்.';
$lang['storage_test_root_error'] = 'கட்டமைக்கப்பட்ட சொத்து கோப்பக சேமிப்பகம் எழுதக்கூடிய உள்ளூர் கோப்பு அமைப்புப் பாதையாக தீர்மானிக்க முடியவில்லை. தற்காலிக சேமிப்பு பயன்படுத்தப்படாது.';
$lang['storage_test_space'] = 'சோதனை மற்றும் அதன் பாதுகாப்பு காப்பு க்காக சொத்து கோப்பக சேமிப்பகம் குறைந்தது 138 MiB இலவசமாக இருக்க வேண்டும்.';
$lang['storage_test_io_error'] = 'ஒரு சேமிப்பு செயல்பாடு தோல்வியடைந்தது அல்லது இடைநீக்கம் செய்யப்பட்டது. சுத்தம் முயற்சிக்கப்படும்; விட்டு வைக்கப்பட்ட கோப்புகள் திட்டமிடப்பட்ட பணிகள் அல்லது அடுத்த சோதனை மூலம் மீண்டும் முயற்சிக்கப்படும்.';
$lang['storage_test_unsafe'] = 'சேமிப்பு மாற்றப்பட்டது அல்லது பாதுகாப்பற்ற கோப்பு கண்டறியப்பட்டது. சோதனை தொடராமல் நிறுத்தப்பட்டது.';
$lang['storage_test_cleanup_error'] = 'சுத்தம் பாதுகாப்பாக முடிக்க முடியவில்லை. திட்டமிடப்பட்ட பணிகள் அல்லது அடுத்த சோதனை மீண்டும் முயற்சிக்கும். கோப்பக அனுமதிகள் மற்றும் சேமிப்பு கிடைக்கும் நிலையை சரிபார்க்கவும்; உண்மையான சொத்துகளை அகற்ற வேண்டாம்.';
$lang['storage_test_connection'] = 'சேமிப்பு சோதனை கோரிக்கை தோல்வியடைந்தது. சுத்தம் முயற்சிக்கப்படும்; விட்டு வைக்கப்பட்ட சோதனைகள் திட்டமிடப்பட்ட பணிகள் அல்லது அடுத்த சோதனை மூலம் மீட்கப்படும்.';
