$lang['storage_test_workload'] = 'பணிச்சுமை நான்கு 16 MiB சொத்துகளை 1 MiB துண்டுகளாக ஸ்ட்ரீம் செய்கிறது, 96 முன்னோட்ட அளவிலான கோப்புகள் (4, 32 மற்றும் 256 KiB), 20 அடுக்குக் கோப்புறைகள் மற்றும் அதிகபட்சம் 64 சீரற்ற 64 KiB வாசிப்புகள். விகிதங்கள் தசம MB ஐ பயன்படுத்துகின்றன. சீரற்ற தாமதம் திறக்க, தேட, வாசிக்க மற்றும் மூடலை உள்ளடக்கியது; p95 அளவீடு அளவிடப்பட்ட மாதிரிகளின் அருகிலுள்ள தரவரிசையை பயன்படுத்துகிறது. சீரற்ற எழுதல்கள் தவிர்க்கப்படுகின்றன ஏனெனில் பதிவேற்றங்கள் மற்றும் முன்னோட்ட உருவாக்கம் பொதுவாக முழுமையான கோப்புகளை எழுதுகின்றன. மெதுவான சேமிப்பில் இந்த பணிச்சுமை குறைக்கப்படலாம்.';
$lang['storage_test_display_error'] = 'சேமிப்பு முன்னேற்றக் காட்சி புதுப்பிக்க முடியவில்லை. உள்ளமைப்பு சரிபார்ப்பை மீண்டும் ஏற்றவும். விட்டு வைக்கப்பட்ட சுத்தம் பாதுகாப்பாக மீண்டும் முயற்சிக்கப்படும்.';
$lang['storage_test_results_heading'] = 'அளவிடப்பட்ட செயல்திறன்';
$lang['storage_test_results_explanation'] = 'மேலே எழுதப்பட்ட மற்றும் வாசிக்கப்பட்ட பைட்டுகள் சோதனை முன்னேற்றத்தை காட்டுகின்றன. கீழே உள்ள முடிவுகள் வேகத்தை அளவிடுகின்றன: அதிக MB/s மற்றும் கோப்புகள் அல்லது செயல்பாடுகள் ஒரு விநாடிக்கு வேகமாகும்; குறைந்த மில்லி விநாடி தாமதம் வேகமாகும். கடந்து/தோல்வி மதிப்பெண் இல்லை.';

$lang['setup-alreadyconfigured'] = 'உங்கள் ResourceSpace நிறுவல் ஏற்கனவே அமைக்கப்பட்டுள்ளது. மீண்டும் அமைக்க, <pre>include/config.php</pre> ஐ நீக்கி, உலாவியில் இந்தப் பக்கத்தை மீண்டும் திறக்கவும்.';

$lang['executecronphp'] = 'பொருத்தமானவற்றைச் சரிபார்க்கும் செயல்பாடு இயங்காது, மேலும் குறிப்பிட்ட கால மின்னஞ்சல் அறிக்கைகள் அனுப்பப்படாது. <a href=\'../batch/cron.php\'>batch/cron.php</a> தினமும் குறைந்தது ஒருமுறையாவது cron வேலை அல்லது அதற்கு இணையான முறையில் இயக்கப்படுவதை உறுதிசெய்யவும்.';

