$lang['collection_edit__introtext'] = 'வளங்களை ஒன்றாகக் குழுவாக்கி உங்கள் பணிகளை ஒழுங்குபடுத்தி நிர்வகிக்கவும். உங்கள் பணிமுறைக்கு ஏற்ற தொகுப்புகளை உருவாக்கவும்.

