<br /><br />';
$lang['collection_email__introtext'] = 'கீழே உள்ள படிவத்தைப் பூர்த்தி செய்யவும்.<br />பெறுநர்கள் கோப்புகளை இணைப்புகளாகப் பெறுவதற்குப் பதிலாக, தொகுப்புகளுக்கான இணைப்புகளைக் கொண்ட மின்னஞ்சல் அல்லது கணினிச் செய்தியைப் பெறுவார்கள். இதன்மூலம் அவர்கள் பொருத்தமான வளங்களைத் தேர்ந்தெடுத்து பதிவிறக்கம் செய்யலாம்.';

$lang['help__introtext'] = '<p>ResourceSpace-ஐ முழுமையாகப் பயன்படுத்துங்கள். இந்த அமைப்பையும் வளங்களையும் மிகவும் திறம்படப் பயன்படுத்த அறிவுத் தளம் உங்களுக்கு உதவும்.</p><p><a href="https://www.resourcespace.com/knowledge-base/" target="_blank" rel="noopener noreferrer">ResourceSpace அறிவுத் தளம்</a></p>';
$lang['research_request__introtext'] = 'உங்கள் திட்டங்களுக்கு மிகச் சிறந்த வளங்களைக் கண்டறிய எங்கள் தொழில்முறை ஆராய்ச்சியாளர்கள் உதவத் தயாராக உள்ளனர். உங்கள் தேவைகளைத் துல்லியமாகப் பூர்த்தி செய்ய, இந்தப் படிவத்தை முடிந்தவரை விரிவாக நிரப்பவும். <br /><br />ஆராய்ச்சிக் குழு உறுப்பினர் ஒருவர் உங்கள் கோரிக்கைக்கு நியமிக்கப்படுவார். செயல்முறை முழுவதும் மின்னஞ்சல் மூலம் உங்களுடன் தொடர்பில் இருப்போம். ஆராய்ச்சி முடிந்ததும், நாங்கள் பரிந்துரைக்கும் அனைத்து வளங்களுக்குமான இணைப்பை மின்னஞ்சலில் பெறுவீர்கள்.  ';
$lang['search_advanced__introtext'] = '<strong>தேடல் குறிப்பு</strong><br />நீங்கள் காலியாக விடும் அல்லது தேர்வுசெய்யாமல் விடும் எந்தப் பிரிவும், அந்தப் பிரிவிலுள்ள எல்லா சொற்களையும் தேடலில் சேர்க்கும். எடுத்துக்காட்டாக, நாட்டுப் பெட்டிகள் அனைத்தையும் காலியாக விட்டால், அந்த நாடுகள் அனைத்திலிருந்தும் முடிவுகள் காட்டப்படும். \'Algeria\' என்பதை மட்டும் தேர்ந்தெடுத்தால், \'Algeria\' நாட்டிலுள்ள வளங்கள் மட்டுமே முடிவுகளில் இடம்பெறும். ';
$lang['team_research__introtext'] = '\'ஆராய்ச்சிக் கோரிக்கைகளை\' ஒழுங்கமைத்து நிர்வகிக்கவும். <br /><br />கோரிக்கை விவரங்களைப் பரிசீலித்து, ஆராய்ச்சியை குழு உறுப்பினருக்கு ஒதுக்க, \'ஆராய்ச்சியைத் திருத்து\' என்பதைத் தேர்ந்தெடுக்கவும். \'திருத்து\' திரையில் தொகுப்பு ID-ஐ உள்ளிடுவதன் மூலம், முந்தைய தொகுப்பின் அடிப்படையில் ஆராய்ச்சிக் கோரிக்கையை உருவாக்கலாம். <br /><br />ஆராய்ச்சிக் கோரிக்கை ஒதுக்கப்பட்டதும், \'தொகுப்பைத் திருத்து\' என்பதைத் தேர்ந்தெடுத்து, ஆராய்ச்சிக் கோரிக்கையை \'இயல்புநிலைத் தொகுப்பு\' பலகத்தில் சேர்க்கவும். பின்னர் நிலையான கருவிகளைப் பயன்படுத்தி, ஆராய்ச்சியில் வளங்களைச் சேர்க்கலாம். <br /><br />ஆராய்ச்சி முடிந்ததும், \'ஆராய்ச்சியைத் திருத்து\' என்பதைத் தேர்ந்தெடுத்து, நிலையை முடிந்தது என மாற்றவும். ஆராய்ச்சியைக் கோரிய பயனருக்கு தானாகவே மின்னஞ்சல் அனுப்பப்படும். அந்த மின்னஞ்சலில் ஆராய்ச்சிக்கான இணைப்பு இருக்கும்; அது அவர்களின் \'இயல்புநிலைத் தொகுப்பு\' பலகத்திலும் தானாகச் சேர்க்கப்படும்.';
$lang['themes__manage'] = 'இணையத்தில் இடம்பெறும் பிரத்யேகத் தொகுப்புகளை ஒழுங்கமைத்து திருத்தவும். பிரத்யேகத் தொகுப்புகள் சிறப்பாக முன்னிலைப்படுத்தப்படும் தொகுப்புகள். <br /><br /> <strong>1 பிரத்யேகத் தொகுப்பின் கீழ் புதிய பதிவை உருவாக்க — ஒரு தொகுப்பை உருவாக்கவும்</strong><br /> முதன்மை மேல்பட்டியிலிருந்து <strong>எனது தொகுப்புகள்</strong> என்பதைத் தேர்ந்தெடுத்து, புதிய <strong>பொது</strong> தொகுப்பை அமைக்கவும். அமைப்பின்போது பிரத்யேகத் தொகுப்பின் பெயரைச் சேர்க்க நினைவில் கொள்ளவும். ஏற்கெனவே உள்ள பிரத்யேகத் தொகுப்பின் பெயரைப் பயன்படுத்தி, அந்தத் தொகுப்பின் கீழ் இதைச் சேர்க்கவும் (பெயரை அப்படியே சரியாக உள்ளிடவும்); அல்லது புதிய பிரத்யேகத் தொகுப்பை உருவாக்கப் புதிய பெயரைத் தேர்ந்தெடுக்கவும். பிரத்யேகத் தொகுப்புகளில் வளங்களைச் சேர்க்கவோ அகற்றவோ பயனர்களை ஒருபோதும் அனுமதிக்க வேண்டாம். <br /> <br /><strong>2 பிரத்யேகத் தொகுப்பின் கீழுள்ள பதிவின் உள்ளடக்கத்தைத் திருத்த</strong><br /> <strong>தொகுப்பைத் திருத்து</strong> என்பதைத் தேர்ந்தெடுக்கவும். அந்தத் தொகுப்பிலுள்ள உருப்படிகள் திரையின் கீழே உள்ள <strong>எனது தொகுப்புகள்</strong> பலகத்தில் தோன்றும். நிலையான கருவிகளைப் பயன்படுத்தி வளங்களைத் திருத்தவும், அகற்றவும் அல்லது சேர்க்கவும். <br /> <br /><strong>3 பிரத்யேகத் தொகுப்பின் பெயரை மாற்ற அல்லது ஒரு தொகுப்பை வேறொரு பிரத்யேகத் தொகுப்பின் கீழ் மாற்ற</strong><br /> <strong>பண்புகளைத் திருத்து</strong> என்பதைத் தேர்ந்தெடுத்து, பிரத்யேகத் தொகுப்பு வகை அல்லது தொகுப்பின் பெயரைத் திருத்தவும். ஏற்கெனவே உள்ள பிரத்யேகத் தொகுப்பின் பெயரைப் பயன்படுத்தி, அந்தத் தொகுப்பின் கீழ் இதைச் சேர்க்கவும் (பெயரை அப்படியே சரியாக உள்ளிடவும்); அல்லது புதிய பிரத்யேகத் தொகுப்பை உருவாக்கப் புதிய பெயரைத் தேர்ந்தெடுக்கவும். <br /> <br /><strong>4 பிரத்யேகத் தொகுப்பிலிருந்து ஒரு தொகுப்பை அகற்ற</strong><br /> <strong>பண்புகளைத் திருத்து</strong> என்பதைத் தேர்ந்தெடுத்து, பிரத்யேகத் தொகுப்பு வகைப் பெட்டியில் உள்ள சொற்களை நீக்கவும். ';
$lang['notify_resource_change_email'] = 'கடந்த [days] நாட்களில் நீங்கள் பதிவிறக்கிய ஒரு வளம் மாற்றப்பட்டுள்ளது. வளத்தைக் காண கீழே உள்ள இணைப்பைக் கிளிக் செய்யவும்.<br /><br /><a href=\'[url]\'>[url]</a>';
$lang['password_reset_email_html'] = 'பயனர்பெயர்: [username]<br /><br />உங்கள் கடவுச்சொல்லை மீட்டமைக்க, கீழே உள்ள இணைப்பைக் கிளிக் செய்யவும்.<br /><br /><a href="[url]" target="_blank" >[url]</a>';
$lang['done__user_password_link_sent'] = 'உங்கள் மின்னஞ்சல் முகவரி செல்லுபடியாகும் கணக்குடன் தொடர்புடையதாக அடையாளம் காணப்பட்டிருந்தால், உங்கள் கடவுச்சொல்லை மீட்டமைப்பதற்கான இணைப்பைக் கொண்ட மின்னஞ்சல் அனுப்பப்பட்டுள்ளது.<br /><br /> மின்னஞ்சல் வரவில்லை என்றால், உங்கள் கணக்கு செல்லுபடியாகும் என நீங்கள் நம்பினால், கணினி நிர்வாகியைத் தொடர்புகொள்வதற்கு முன் உங்கள் மின்னஞ்சல் வடிகட்டிகளைச் சரிபார்க்கவும்.';

$lang['information-geomapping'] = 'இந்த புலத்தில் புவியியல் இடத்தை அகலம், நீளம் அல்லது இரண்டையும் சேமிக்கவும்.<br />ஒரே புலம் இரண்டையும் அல்லது ஒரு புலம் அகலமாகவும் மற்றொரு புலம் நீளமாகவும் அமைக்கப்படலாம்.<br />இது ஒரே வரிசை உரை புலங்களுக்கு மட்டுமே கிடைக்கும்.';
$lang['accountdoesnotexist'] = 'இந்த பயனர் கணக்கு இல்லை.<br />நீங்கள் பயனர் செய்தி பகுதியில் உள்ள இணைப்பின் மூலம் இந்தப் பக்கத்திற்கு வந்திருந்தால், மற்றொரு நிர்வாகி ஏற்கனவே கணக்கு கோரிக்கையை கையாள்ந்து இந்தக் கணக்கை நீக்கியிருக்கலாம் என்பதை கவனிக்கவும்.';
$lang['contactsheetintrotext'] = 'உங்கள் தொடர்பு தாள் PDF க்கான கட்டமைப்பு விருப்பங்களைத் தேர்ந்தெடுக்கவும். உங்கள் விருப்பங்களை மாற்றும்போது முன்னோட்டம் தானாக புதுப்பிக்கப்படும். நீங்கள் தேர்ந்தெடுத்த மெட்டாடேட்டா புலங்கள் அல்லது தொகுப்பில் உள்ள வளங்களின் வரிசையை மாற்றினால், "முன்னோட்டத்தை புதுப்பி" பொத்தானை அழுத்தி புதுப்பிக்க வேண்டும்.<br />தயாராக இருந்தால், "உருவாக்கு" பொத்தானை அழுத்தி உங்கள் தொடர்பு தாள் PDF ஐ உருவாக்கி பதிவிறக்கவும்.';
$lang['requestfeedback'] = 'கோரிக்கை கருத்து<br />(உங்களுக்கு பதில் மின்னஞ்சல் அனுப்பப்படும்)';
$lang['feedbacknocomments'] = 'தொகுப்பில் உள்ள வளங்களுக்கு நீங்கள் எந்த கருத்துகளையும் விடவில்லை.<br />ஒவ்வொரு வளத்தின் அருகிலுள்ள உரையாடல் புலத்தை கிளிக் செய்து கருத்துகளைச் சேர்க்கவும்.';
$lang['exportdata-instructions'] = 'இது உங்கள் அமைப்பிலிருந்து கணினி அமைப்பு தரவை ஏற்றுமதி செய்யும், பிழைதிருத்த நோக்கத்திற்காக. அனைத்து தரவுகளும் (புல விருப்பங்கள், பயனர் பெயர்கள், மின்னஞ்சல்கள் மற்றும் மெட்டாடேட்டா போன்றவை) உங்கள் சேவையக நிர்வாகியின் அனுமதி இல்லாமல் மறைக்கப்படும்.</br>நீங்கள் ஏற்றுமதி செய்ய விரும்பும் தகவலைத் தேர்ந்தெடுத்து \'ஏற்றுமதி\' என்பதைக் கிளிக் செய்யவும். ஒரு ஆஃப்லைன் வேலை உருவாக்கப்படும் மற்றும் உங்கள் பதிவிறக்கம் தயாராகும் போது அறிவிப்பு கிடைக்கும்.';
$lang['cannotemailpassword'] = 'பயனருக்கு அவர்களது தற்போதைய கடவுச்சொல்லை மின்னஞ்சல் செய்ய முடியாது, ஏனெனில் அது சேமிக்கப்படவில்லை (மாறாக குறியாக்க ஹாஷ் சேமிக்கப்பட்டுள்ளது).<br /><br />மேலே உள்ள \'பரிந்துரை\' பொத்தானை பயன்படுத்த வேண்டும், இது புதிய கடவுச்சொல்லை உருவாக்கி மின்னஞ்சல் செயல்பாட்டை இயக்கு.';
$lang['setup-checkerrors'] = 'முன்-கட்டமைப்பு பிழைகள் கண்டறியப்பட்டன.<br />  தயவுசெய்து இந்த பிழைகளை சரி செய்து இந்தப் பக்கத்திற்கு திரும்பி தொடரவும்.';
$lang['tagcloudtext'] = 'மக்கள் எந்த மெட்டாடேட்டா சொற்களை பயன்படுத்தி வளங்களை குறிச்சொல்லாக வைத்துள்ளனர்? ஒரு சொல் அதிகம் பயன்படுத்தப்பட்டால் அது மேகத்தில் பெரியதாக தோன்றும்.<br /><br />கீழே உள்ள எந்த சொல்லையும் கிளிக் செய்து தேடலை இயக்கலாம்.';
$lang['oj_purge_duplicates_intro'] = '<strong>எச்சரிக்கை: இந்த ஸ்கிரிப்ட் வளங்களை நிரந்தரமாக நீக்க அனுமதிக்கிறது - நீங்கள் உறுதியாக இல்லாவிட்டால் உங்கள் அமைப்புகளை சரிபார்க்க \'உலர் ஓட்டம்\' விருப்பத்தை பயன்படுத்தவும்.</strong>';
